using Alterverse.Combat;using Alterverse.Match;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.UI
{
public sealed class TargetIndicatorHUD:MonoBehaviour
{
private SoftTargeting targeting;private Camera cachedCamera;private Texture2D pixel;private GUIStyle label;private float nextResolve;private void Start(){pixel=new Texture2D(1,1);pixel.SetPixel(0,0,Color.white);pixel.Apply();cachedCamera=Camera.main;ResolveTargeting();}private void Update(){if(targeting==null&&Time.unscaledTime>=nextResolve)ResolveTargeting();if(cachedCamera==null)cachedCamera=Camera.main;}
private void ResolveTargeting(){nextResolve=Time.unscaledTime+.5f;PlayerHeroAbilities player=FindAnyObjectByType<PlayerHeroAbilities>();if(player!=null)targeting=player.GetComponent<SoftTargeting>();}
private void OnGUI(){Health h=targeting!=null?targeting.Current:null;if(h==null||cachedCamera==null)return;Vector3 s=cachedCamera.WorldToScreenPoint(h.transform.position+Vector3.up*1.25f);if(s.z<=0||s.x<-80||s.x>Screen.width+80||s.y<-80||s.y>Screen.height+80)return;s.y=Screen.height-s.y;bool objective=h.GetComponent<DimensionPlanet>()!=null;float pulse=1f+Mathf.Sin(Time.unscaledTime*5f)*.08f,size=(objective?64:48)*pulse;Color c=objective?StylizedArtDirection.WarmAccent:new Color(1,.25f,.28f,.95f);Color old=GUI.color;GUI.color=c;float t=objective?4:3,arm=size*.27f;GUI.DrawTexture(new Rect(s.x-size*.5f,s.y-size*.5f,arm,t),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-arm,s.y-size*.5f,arm,t),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y+size*.5f-t,arm,t),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-arm,s.y+size*.5f-t,arm,t),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y-size*.5f,t,arm),pixel);GUI.DrawTexture(new Rect(s.x-size*.5f,s.y+size*.5f-arm,t,arm),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-t,s.y-size*.5f,t,arm),pixel);GUI.DrawTexture(new Rect(s.x+size*.5f-t,s.y+size*.5f-arm,t,arm),pixel);GUI.color=new Color(c.r,c.g,c.b,.45f);GUI.DrawTexture(new Rect(s.x-1,s.y-size*.68f,2,size*.18f),pixel);GUI.DrawTexture(new Rect(s.x-1,s.y+size*.5f,2,size*.18f),pixel);GUI.color=old;label??=new GUIStyle(GUI.skin.label){fontSize=11,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};GUI.Label(new Rect(s.x-70,s.y-size*.5f-22,140,20),objective?"DIMENSION OBJECTIVE":"SOFT TARGET",label);}
private void OnDestroy(){if(pixel!=null)Destroy(pixel);}
}
}
